نقش سازمانی: store_operations_manager (store_operations_manager)

درخواست کاربر:
ریشه‌یابی افت فروش «شعبهٔ ۴۰» با تفکیک ترافیک و تبدیل. (مرکز)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "foot_traffic",
      "description": "ترافیک و تراکنش روزانهٔ شعبه",
      "dimensions": [
        "branch",
        "day"
      ],
      "measures": [
        "visitors",
        "transactions"
      ]
    },
    {
      "dataset": "replenishment_log",
      "description": "تأخیر و پرشدن خطوط مکمل از مرکز توزیع",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "delay_days",
        "lines_filled_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "conversion_rate",
      "description": "نرخ تبدیل ترافیک به خرید",
      "formula": "تراکنش تقسیم بر بازدیدکننده",
      "unit": "درصد",
      "dimensions": [
        "branch"
      ]
    }
  ],
  "business_context": [
    "استاندارد چک‌لیست ماهانه برای همهٔ شعب",
    "۱۲۰ شعبه در پنج منطقه با سرپرست منطقه‌ای",
    "دوربین شمارش ترافیک در ورودی همهٔ شعب"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "foot_traffic",
    "filters": {
      "branch": "شعبهٔ ۴۰",
      "period": [
        "prev_week",
        "curr_week"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "visitors": {
    "prev": 30500,
    "curr": 30831,
    "change_pct": 1.1
  },
  "transactions": {
    "prev": 7442,
    "curr": 6259
  },
  "conversion_pct": {
    "prev": 24.4,
    "curr": 20.3,
    "change_pp": -4.1
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "replenishment_log",
    "filters": {
      "branch": "شعبهٔ ۴۰",
      "period": "curr_week"
    }
  }
}

نقش سازمانی: store_operations_manager (store_operations_manager)

درخواست کاربر:
گزارش هفتگی منطقهٔ شمال را بده: فروش هر مترمربع و تبدیل شعبه‌ها. (سرپرست شمال)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "store_pnl",
      "description": "فروش و بودجهٔ هفتگی هر شعبه",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "sales_m",
        "budget_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "sales_per_sqm",
      "description": "فروش هر مترمربع",
      "formula": "فروش تقسیم بر مساحت فروشگاه",
      "unit": "هزار تومان",
      "dimensions": [
        "branch"
      ]
    },
    {
      "metric": "conversion_rate",
      "description": "نرخ تبدیل ترافیک به خرید",
      "formula": "تراکنش تقسیم بر بازدیدکننده",
      "unit": "درصد",
      "dimensions": [
        "branch"
      ]
    }
  ],
  "business_context": [
    "مرکز توزیع واحد، مکمل‌گیری روزانهٔ شعب",
    "استاندارد چک‌لیست ماهانه برای همهٔ شعب",
    "دوربین شمارش ترافیک در ورودی همهٔ شعب"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "store_pnl",
    "filters": {
      "region": "شمال",
      "period": "this_week"
    }
  }
}

