نقش سازمانی: store_operations_manager (store_operations_manager)

درخواست کاربر:
چرا «شعبهٔ ۶۶» بهتر از «شعبهٔ ۲۵» می‌فروشد؟ عدد بده. (جنوب)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "store_pnl",
      "description": "فروش و بودجهٔ هفتگی هر شعبه",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "sales_m",
        "budget_m"
      ]
    },
    {
      "dataset": "checklist_audits",
      "description": "امتیاز چک‌لیست بازرسی شعبه",
      "dimensions": [
        "branch",
        "month"
      ],
      "measures": [
        "score",
        "fail_count"
      ]
    },
    {
      "dataset": "labor_hours",
      "description": "ساعات کار نیروی فروش هفتگی",
      "dimensions": [
        "branch",
        "week"
      ],
      "measures": [
        "hours",
        "overtime_hours"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "sales_per_sqm",
      "description": "فروش هر مترمربع",
      "formula": "فروش تقسیم بر مساحت فروشگاه",
      "unit": "هزار تومان",
      "dimensions": [
        "branch"
      ]
    },
    {
      "metric": "conversion_rate",
      "description": "نرخ تبدیل ترافیک به خرید",
      "formula": "تراکنش تقسیم بر بازدیدکننده",
      "unit": "درصد",
      "dimensions": [
        "branch"
      ]
    },
    {
      "metric": "checklist_score",
      "description": "امتیاز چک‌لیست بازرسی",
      "formula": "میانگین امتیاز بازرسی‌های ماه",
      "unit": "از ۱۰۰",
      "dimensions": [
        "branch"
      ]
    },
    {
      "metric": "labor_pct",
      "description": "سهم هزینهٔ نیروی کار از فروش",
      "formula": "هزینهٔ نیروی کار تقسیم بر فروش",
      "unit": "درصد",
      "dimensions": [
        "branch"
      ]
    }
  ],
  "business_context": [
    "۱۲۰ شعبه در پنج منطقه با سرپرست منطقه‌ای",
    "مرکز توزیع واحد، مکمل‌گیری روزانهٔ شعب",
    "هدف‌گذاری فروش هفتگی برای هر شعبه"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "store_pnl",
    "filters": {
      "branch": [
        "شعبهٔ ۶۶",
        "شعبهٔ ۲۵"
      ],
      "period": "this_month"
    }
  }
}

