{
  "tool": "get_dataset",
  "arguments": {
    "name": "store_pnl",
    "filters": {
      "branch": [
        "شعبهٔ ۷۰",
        "شعبهٔ ۶۱"
      ],
      "period": "this_month"
    }
  }
}

